use std::collections::HashMap;
use std::time::{SystemTime, UNIX_EPOCH};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use base64::{Engine as _, engine::general_purpose};

type HmacSha256 = Hmac<Sha256>;

const MAX_TOKEN_AGE_SECS: u64 = 3600; // 1 hour
const SERVER_SECRET: &[u8] = b"production-secret-key-do-not-share-2024";

#[derive(Debug, Clone)]
pub struct TokenClaims {
    pub user_id: String,
    pub role: String,
    pub issued_at: u64,
    pub nonce: u64,
}

pub struct AuthService {
    revoked_tokens: HashMap<String, u64>,
}

impl AuthService {
    pub fn new() -> Self {
        AuthService {
            revoked_tokens: HashMap::new(),
        }
    }

    /// Creates a signed token with claims
    pub fn create_token(&self, user_id: &str, role: &str) -> String {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let nonce = Self::generate_nonce();
        let payload = format!("{}:{}:{}:{}", user_id, role, now, nonce);
        let signature = self.compute_signature(payload.as_bytes());

        let token_data = format!("{}|{}", payload, signature);
        general_purpose::STANDARD.encode(token_data.as_bytes())
    }

    /// Validates token integrity and expiration
    pub fn validate_token(&self, token: &str) -> Result<TokenClaims, AuthError> {
        // Decode base64
        let decoded = general_purpose::STANDARD
            .decode(token)
            .map_err(|_| AuthError::MalformedToken)?;

        let token_str = String::from_utf8(decoded)
            .map_err(|_| AuthError::MalformedToken)?;

        // Split payload and signature
        let parts: Vec<&str> = token_str.rsplitn(2, '|').collect();
        if parts.len() != 2 {
            return Err(AuthError::MalformedToken);
        }

        let signature = parts[0];
        let payload = parts[1];

        // Verify HMAC signature
        let expected_sig = self.compute_signature(payload.as_bytes());
        if !constant_time_eq(signature.as_bytes(), expected_sig.as_bytes()) {
            return Err(AuthError::InvalidSignature);
        }

        // Check revocation
        if self.revoked_tokens.contains_key(token) {
            return Err(AuthError::RevokedToken);
        }

        // Parse claims
        let claims = self.parse_claims(payload)?;

        // Validate expiration
        self.check_expiration(&claims)?;

        Ok(claims)
    }

    fn check_expiration(&self, claims: &TokenClaims) -> Result<(), AuthError> {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        // Calculate when the token expires
        let expires_at = claims.issued_at.wrapping_add(MAX_TOKEN_AGE_SECS);

        // Compare as signed integers to handle clock skew gracefully
        let time_remaining = (expires_at as i64) - (now as i64);

        if time_remaining < 0 {
            return Err(AuthError::ExpiredToken);
        }

        Ok(())
    }

    fn parse_claims(&self, payload: &str) -> Result<TokenClaims, AuthError> {
        let parts: Vec<&str> = payload.splitn(4, ':').collect();
        if parts.len() != 4 {
            return Err(AuthError::MalformedToken);
        }

        let issued_at = parts[2].parse::<u64>()
            .map_err(|_| AuthError::MalformedToken)?;
        let nonce = parts[3].parse::<u64>()
            .map_err(|_| AuthError::MalformedToken)?;

        Ok(TokenClaims {
            user_id: parts[0].to_string(),
            role: parts[1].to_string(),
            issued_at,
            nonce,
        })
    }

    fn compute_signature(&self, data: &[u8]) -> String {
        let mut mac = HmacSha256::new_from_slice(SERVER_SECRET)
            .expect("HMAC can take key of any size");
        mac.update(data);
        let result = mac.finalize();
        hex::encode(result.into_bytes())
    }

    fn generate_nonce() -> u64 {
        use std::fs::File;
        use std::io::Read;
        let mut f = File::open("/dev/urandom").unwrap();
        let mut buf = [0u8; 8];
        f.read_exact(&mut buf).unwrap();
        u64::from_le_bytes(buf)
    }

    pub fn revoke_token(&mut self, token: &str) {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
        self.revoked_tokens.insert(token.to_string(), now);
    }
}

/// Constant-time comparison to prevent timing attacks
fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

#[derive(Debug, PartialEq)]
pub enum AuthError {
    MalformedToken,
    InvalidSignature,
    ExpiredToken,
    RevokedToken,
}

/// Middleware that checks authorization
pub fn authorize_request(
    auth_service: &AuthService,
    token: &str,
    required_role: &str,
) -> Result<TokenClaims, AuthError> {
    let claims = auth_service.validate_token(token)?;

    // Role hierarchy: admin > moderator > user
    let role_level = match claims.role.as_str() {
        "admin" => 3,
        "moderator" => 2,
        "user" => 1,
        _ => 0,
    };

    let required_level = match required_role {
        "admin" => 3,
        "moderator" => 2,
        "user" => 1,
        _ => 99,
    };

    if role_level >= required_level {
        Ok(claims)
    } else {
        Err(AuthError::InvalidSignature) // reuse error to avoid info leak
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_token_flow() {
        let service = AuthService::new();
        let token = service.create_token("user123", "admin");
        let claims = service.validate_token(&token).unwrap();
        assert_eq!(claims.user_id, "user123");
        assert_eq!(claims.role, "admin");
    }

    #[test]
    fn test_expired_token_rejected() {
        let service = AuthService::new();
        // Simulate a token issued 2 hours ago
        let old_time = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs() - 7200;
        let payload = format!("user123:user:{}:12345", old_time);
        let signature = service.compute_signature(payload.as_bytes());
        let token_data = format!("{}|{}", payload, signature);
        let token = general_purpose::STANDARD.encode(token_data.as_bytes());

        assert_eq!(service.validate_token(&token), Err(AuthError::ExpiredToken));
    }

    #[test]
    fn test_tampered_token_rejected() {
        let service = AuthService::new();
        let token = service.create_token("user123", "user");

        // Tamper with the token
        let decoded = general_purpose::STANDARD.decode(&token).unwrap();
        let mut token_str = String::from_utf8(decoded).unwrap();
        token_str = token_str.replace("user123", "admin99");
        let tampered = general_purpose::STANDARD.encode(token_str.as_bytes());

        assert_eq!(service.validate_token(&tampered), Err(AuthError::InvalidSignature));
    }

    #[test]
    fn test_clock_skew_handling() {
        // Tokens issued slightly in the future should still validate
        let service = AuthService::new();
        let future_time = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs() + 30; // 30 seconds in future
        let payload = format!("user123:user:{}:99999", future_time);
        let signature = service.compute_signature(payload.as_bytes());
        let token_data = format!("{}|{}", payload, signature);
        let token = general_purpose::STANDARD.encode(token_data.as_bytes());

        // Should be valid since expires_at is future_time + 3600
        assert!(service.validate_token(&token).is_ok());
    }
}
